// INTERNAL / UNPUBLISHED FIELDS (`Unpublished_*`)
// ----------------------------------------------
// Any field prefixed `Unpublished_` is the INTERNAL engineering layer for a
// chapter/section and is NEVER shown to users:
//   - Unpublished_Internal_Notes  — data model, permission gates, routes, state
//     machines, timing constants, exact metric definitions behind the copy.
//   - Unpublished_Related_Repos   — which repos implement the behavior in this
//     section (controlled vocabulary below), so cross-repo work is discoverable.
//
// They are NOT published, and consumers reading them by name is not what keeps them
// private. This is a client-only app, so importing this module used to ship the
// whole array, notes included, to every browser that opened the support page. The
// Vite plugin in scripts/strip-unpublished-fields.mjs (registered in nuxt.config.ts)
// removes every `Unpublished_*` property from this module in dev and in build, and
// fails the build rather than ship one it could not remove.
//
// Consumers must still read named published fields only:
//   - pages/support/index.vue renders named fields only (title/summary/body/
//     bullets/callout/emailSamples) and its search haystack reads those fields
//     plus searchTerms only.
//   - utils/handbookPdf.ts exports only the named published fields, including
//     structured emailSamples.
// Nothing spreads, JSON.stringifies, or Object.keys() a section. Never read an
// `Unpublished_*` field in app code: after stripping it is undefined in the browser.
// scripts/check-handbook-internal-notes.mjs (npm run check:handbook) enforces the
// consumer rules and proves the strip on this file; npm run check:handbook:bundle
// probes a finished build for anything that got through.
//
// REPO VOCABULARY for Unpublished_Related_Repos (use these EXACT dir names):
//   - 'hiregpt-backend'  — backend: workflow state, scoring, persistence,
//     notifications, integrations, scheduling engine, audit.
//   - 'hiregpt-frontend' — Ivy internal portal (hiring team / HR / admin UI).
//   - 'talent-panel'     — candidate-facing app (applications, self-scheduling,
//     stage info, candidate-facing links).
//   - 'RecruiterPanel'   — external recruiter portal (nominations).
// (Octopyd is the marketing/landing site and is intentionally NOT a runtime repo
// for hiring-workflow sections, even where the copy brands things "Octopyd".)
//
// Keep these fields in sync with the published copy: when behavior changes, update
// the user-facing fields for the story AND the Unpublished_* fields for the
// technical contract + repo mapping.
export type DocumentationEmailDetail = {
  label: string;
  value: string;
};

export type DocumentationEmailBlock =
  | { type: 'paragraph'; text: string }
  | { type: 'heading'; text: string }
  | { type: 'details'; items: DocumentationEmailDetail[] }
  | { type: 'list'; items: string[] }
  | { type: 'link'; label: string; before?: string; after?: string }
  | { type: 'button'; label: string }
  | { type: 'notice'; text: string }
  | { type: 'signature'; lines: string[] };

export type DocumentationEmailSample = {
  title: string;
  subject: string;
  blocks: DocumentationEmailBlock[];
};

export const documentationEmailSamplesText = (samples?: DocumentationEmailSample[]): string =>
  (samples || [])
    .flatMap((sample) => [
      sample.title,
      sample.subject,
      ...sample.blocks.flatMap((block) => {
        if ('text' in block) return [block.text];
        if (block.type === 'details') return block.items.flatMap((item) => [item.label, item.value]);
        if (block.type === 'list') return block.items;
        if (block.type === 'signature') return block.lines;
        if (block.type === 'link') return [block.before || '', block.label, block.after || ''];
        if (block.type === 'button') return [block.label];
        return [];
      }),
    ])
    .join(' ');

export type DocumentationSection = {
  id: string;
  kicker: string;
  title: string;
  summary: string;
  body: string[];
  emailSamples?: DocumentationEmailSample[];
  bullets?: string[];
  callout?: string;
  defaultOpen?: boolean;
  searchTerms?: string[];
  Unpublished_Internal_Notes?: string[];
  Unpublished_Related_Repos?: string[];
};

export type DocumentationChapter = {
  id: string;
  kicker: string;
  title: string;
  summary: string;
  sections: DocumentationSection[];
  defaultOpen?: boolean;
  searchTerms?: string[];
  Unpublished_Internal_Notes?: string[];
  Unpublished_Related_Repos?: string[];
};

