        searchTerms: ['reconnect mailbox', 'disconnect mailbox', 'mailbox not connected', 'different mailbox', 'ai managed mailbox', 'shared free busy', 'calendar sync settings', 'calendar invite', 'meeting invite', 'event organizer', 'interview title', 'candidate profile link', 'talent portal link', 'calendar monitor', 'sender name', 'from name', 'display name', 'room discovery', 'mailbox rooms', 'import rooms through mailbox'],
